function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2400)}
let renderedViewportKey=location.hash,viewportRestoreToken=0,viewportSettleTimer=null;
const teacherScrollSelectors=['.teacher-sidebar','.teacher-main','.teacher-content','.teacher-attention-scroll','.attention-progress-list','.attention-event-list','.attention-student-list','#roster-list'];
function captureTeacherScrollAreas(){
 const areas=[];
 teacherScrollSelectors.forEach(selector=>app.querySelectorAll(selector).forEach((el,index)=>areas.push({selector,index,top:el.scrollTop,left:el.scrollLeft})));
 return areas;
}
function restoreViewportAfterRender(scrollX,scrollY,key,areas=[]){
 const token=++viewportRestoreToken;
 clearTimeout(viewportSettleTimer);
 const restore=()=>{
  if(token!==viewportRestoreToken||location.hash!==key)return;
  if(scrollX>0||scrollY>0)window.scrollTo({left:scrollX,top:scrollY,behavior:'instant'});
  areas.forEach(area=>{if(area.top<=0&&area.left<=0)return;const el=app.querySelectorAll(area.selector)[area.index];if(el){if(area.top>0)el.scrollTop=area.top;if(area.left>0)el.scrollLeft=area.left}});
 };
 requestAnimationFrame(()=>{restore();app.style.minHeight=''});
}
function openDialog(title,body,actions=''){dialogRoot.innerHTML=`<div class="dialog-backdrop" data-dialog-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2>${body}<div class="dialog-actions">${actions||'<button class="btn btn-primary" data-close-dialog>Done</button>'}</div></section></div>`;dialogRoot.querySelector('[data-close-dialog]')?.addEventListener('click',closeDialog);dialogRoot.querySelector('[data-dialog-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeDialog()});dialogRoot.querySelector('button')?.focus()}
function closeDialog(){const commandActive=!!dialogRoot.querySelector('#apply-student-command');dialogRoot.innerHTML='';if(commandActive&&state.pendingCommand){state.pendingCommand='';render()}}
function escapeHtml(value){return String(value??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function teacherPassTiming(row,now=Date.now()){return window.DWV33Passes?.passTiming(row?.startedMs,now)||{remainingMs:0,overdueMs:0,overdue:false}}
function formatTeacherPassDuration(ms){const seconds=Math.max(0,Math.ceil(Number(ms||0)/1000)),minutes=Math.floor(seconds/60);return `${minutes}:${String(seconds%60).padStart(2,'0')}`}
function teacherPassCountdownText(row,now=Date.now()){const timing=teacherPassTiming(row,now);return timing.overdue?`OVERDUE +${formatTeacherPassDuration(timing.overdueMs)}`:`${formatTeacherPassDuration(timing.remainingMs)} left`}
function teacherPassTimerMarkup(row){const text=teacherPassCountdownText(row);return `<input class="teacher-pass-countdown ${teacherPassTiming(row).overdue?'overdue':''}" data-teacher-pass-timer data-started-ms="${Number(row?.startedMs)||0}" value="${escapeHtml(text)}" aria-label="Pass timer: ${escapeHtml(text)}" readonly tabindex="-1">`}
function syncTeacherPassTimers(){document.querySelectorAll('[data-teacher-pass-timer]').forEach(timer=>{const timing=window.DWV33Passes?.passTiming(Number(timer.dataset.startedMs)||0,Date.now())||{remainingMs:0,overdueMs:0,overdue:false},text=timing.overdue?`OVERDUE +${formatTeacherPassDuration(timing.overdueMs)}`:`${formatTeacherPassDuration(timing.remainingMs)} left`;if(timer.value!==text)timer.value=text;timer.setAttribute('aria-label',`Pass timer: ${text}`);timer.classList.toggle('overdue',timing.overdue)})}
function startTeacherPassTimers(){clearInterval(teacherPassTimerInterval);teacherPassTimerInterval=null;syncTeacherPassTimers();if(document.querySelector('[data-teacher-pass-timer]'))teacherPassTimerInterval=setInterval(syncTeacherPassTimers,1000)}
function currentPage(){const h=location.hash.replace('#','');return teacherNavItems().some(n=>n[0]===h)?h:'student-command'}
function navMarkup(){
 const items=teacherNavItems(),groups=['Command','Classroom','Administration','Free Time'];
 return `<nav class="teacher-nav" aria-label="Teacher portal">${groups.map(group=>{const groupId=`teacher-nav-${group.toLowerCase().replace(/\s+/g,'-')}`,groupItems=items.filter(item=>item[4]===group);if(!groupItems.length)return '';return `<section class="teacher-nav-group" aria-labelledby="${groupId}"><div class="nav-group-title" id="${groupId}">${group}</div><div class="teacher-nav-list">${groupItems.map(([id,icon,label,sub])=>`<button class="nav-link ${state.page===id?'active':''}" type="button" data-page="${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon"><img class="teacher-nav-icon" src="${icon}" alt=""></span><span><span class="nav-main">${label}</span><span class="nav-sub">${sub}</span></span></button>`).join('')}</div></section>`}).join('')}</nav>`;
}
