function calendarMonthShift(month,delta){const [year,value]=String(month).split('-').map(Number),date=new Date(Date.UTC(year,value-1+delta,1));return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`}
