function enhanceLiveTeacherUi(){
 installArcadeFreeControls();
 const summaryActions=[recognitionReview,manageDailyAccess,reviewCurriculumOverrides];
 app.querySelectorAll('.attention-strip .attention-item').forEach((card,index)=>{card.classList.add('clickable-summary');card.tabIndex=0;card.setAttribute('role','button');const open=event=>{if(event?.target?.closest('button'))return;summaryActions[index]?.()};card.addEventListener('click',open);card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open(event)}})});
 app.querySelectorAll('.attention-strip .attention-score').forEach(card=>{card.classList.add('clickable-summary');card.tabIndex=0;card.setAttribute('role','button');card.addEventListener('click',showPointLedger);card.addEventListener('keydown',event=>{if(event.key==='Enter')showPointLedger()})});
  if(state.page==='gradebook'){
   const headers=app.querySelectorAll('.grade-table th');if(headers[1])headers[1].textContent='Total / Status';if(headers[4])headers[4].textContent='Storyvault Time';if(headers[5])headers[5].textContent='Incomplete';
   const weightLabels=app.querySelectorAll('.weight-label span');if(weightLabels[3])weightLabels[3].textContent='Storyvault Reading';
   const metricLabels=app.querySelectorAll('.metric .eyebrow');metricLabels.forEach(label=>{if(label.textContent==='Missing categories')label.textContent='Incomplete work'});
  }
  if(state.page==='storyvault')app.querySelector('[data-reading-settings]')?.addEventListener('click',editReadingAssignment);
 if(state.page==='rewards'){
   const shared=app.querySelector('.class-points');if(shared){shared.classList.add('clickable-summary');shared.tabIndex=0;shared.addEventListener('click',event=>{if(!event.target.closest('button,input,select'))showGoalEvidence('main')});shared.addEventListener('keydown',event=>{if(event.key==='Enter')showGoalEvidence('main')})}
   const bank=app.querySelector('.flex-bank');if(bank){bank.classList.add('clickable-summary');bank.tabIndex=0;bank.addEventListener('click',event=>{if(!event.target.closest('button,input,select'))showGoalEvidence('universalPoints')})}
   app.querySelectorAll('.goal-card').forEach(card=>{card.classList.add('clickable-summary');card.tabIndex=0;const goalId=card.querySelector('[data-goal-id]')?.dataset.goalId;const open=event=>{if(event?.target?.closest('button'))return;showGoalEvidence(goalId)};card.addEventListener('click',open);card.addEventListener('keydown',event=>{if(event.key==='Enter'){open(event)}})});
 }
 if(state.page==='jobs')app.querySelectorAll('.metric-grid .metric').forEach((card,index)=>{card.classList.add('clickable-summary');card.tabIndex=0;card.addEventListener('click',()=>showJobMetric(index));card.addEventListener('keydown',event=>{if(event.key==='Enter')showJobMetric(index)})});
}
function installArcadeFreeControls(){
 if(state.page!=='arcade'||app.querySelector('[data-arcade-free-controls]'))return;
 const selected=students.filter(student=>state.selected.has(student.id)),panel=document.createElement('section');panel.className='panel teacher-form';panel.dataset.arcadeFreeControls='1';
 panel.innerHTML=`<div class="eyebrow">ONE-HOUR OVERRIDE</div><h3>Free Arcade • bypass every lock</h3><p>Morning Work, Curriculum, Token, class, and individual Arcade locks are bypassed. No Tokens are charged.</p><div class="row mt-12"><button class="btn btn-primary" type="button" data-arcade-free-class>🕹️ Free Arcade for Everyone • 1 Hour</button><button class="btn btn-secondary" type="button" data-arcade-free-selected ${selected.length?'':'disabled'}>👤 Free Arcade for Selected • 1 Hour</button></div><div class="row mt-12"><button class="btn btn-danger" type="button" data-arcade-restore-all>🔒 Restore All Restrictions</button><button class="btn btn-secondary" type="button" data-arcade-restore-selected ${selected.length?'':'disabled'}>🔒 Restore Selected Student</button></div><p class="muted mt-12">${selected.length?escapeHtml(selected.map(student=>student.name).join(', ')):'Choose one or more scholars below for individual free access or restoration.'}</p>`;
 app.querySelector('.teacher-content .teacher-form')?.before(panel);
 panel.querySelector('[data-arcade-free-class]')?.addEventListener('click',()=>setArcadeFreeAccess('class'));
 panel.querySelector('[data-arcade-free-selected]')?.addEventListener('click',()=>setArcadeFreeAccess('individual'));
 panel.querySelector('[data-arcade-restore-all]')?.addEventListener('click',()=>restoreArcadeRestrictions('all'));
 panel.querySelector('[data-arcade-restore-selected]')?.addEventListener('click',()=>restoreArcadeRestrictions('individual'));
}
async function runArcade(action,success){
 if(!arcadeTeacher?.enabled){showToast('Arcade controls are unavailable in this environment.');return}
 state.arcadeBusy=true;render();
 try{await action();showToast(success)}catch(err){showToast(err?.message||'Arcade command failed.')}finally{state.arcadeBusy=false;render()}
}
async function refreshArcadeTeacher(){
 const chosen=students.filter(s=>state.selected.has(s.id));
 if(!chosen.length){showToast('Select at least one scholar first.');return}
 await runArcade(async()=>{const pairs=await Promise.all(chosen.map(async s=>[s.id,await arcadeTeacher.getState(s.id)]));for(const [id,value] of pairs)state.arcadeRows[id]=value},'Arcade status refreshed.');
}
async function awardArcade(criterion){
 const ids=[...state.selected];
 if(!ids.length){showToast('Select at least one scholar first.');return}
 await runArcade(async()=>{await Promise.all(ids.map(uid=>arcadeTeacher.award(uid,criterion)));const pairs=await Promise.all(ids.map(async uid=>[uid,await arcadeTeacher.getState(uid)]));for(const [id,value] of pairs)state.arcadeRows[id]=value},`${criterion[0].toUpperCase()+criterion.slice(1)} Token criterion processed.`);
}
function setArcadeClass(enabled){
 const destination=window.DWV33Integration?.environment==='manual-preview'?'this browser’s isolated preview state':writeDestination();
 openDialog(`${enabled?'Open':'Lock'} Arcade Time?`,`<p>${enabled?'The class may start Arcade when each scholar has 3 Tokens.':'Every active Arcade session will be stopped by the authoritative server lock.'}</p><p class="muted">This command writes only to ${destination}.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn ${enabled?'btn-primary':'btn-danger'}" id="confirm-arcade-class">${enabled?'Open class access':'Lock class now'}</button>`);
 dialogRoot.querySelector('#confirm-arcade-class')?.addEventListener('click',async()=>{closeDialog();await runArcade(()=>arcadeTeacher.setAvailability(enabled),`Class Arcade Time ${enabled?'opened':'locked'}.`)});
}
async function setArcadeIndividual(uid,enabled){await runArcade(async()=>{await arcadeTeacher.setAvailability(enabled,uid);state.arcadeRows[uid]=await arcadeTeacher.getState(uid)},`Scholar Arcade access ${enabled?'opened':'locked'}.`)}
function setArcadeFreeAccess(scope){
 const selected=students.filter(student=>state.selected.has(student.id));if(scope==='individual'&&!selected.length){showToast('Choose at least one scholar first.');return}
 const names=selected.map(student=>student.name).join(', '),label=scope==='class'?'everyone':names;
 openDialog('Start free Arcade for one hour?',`<p><b>${escapeHtml(label)}</b> will bypass Morning Work, Curriculum, Token, class, and individual Arcade locks for exactly one hour.</p><p class="muted">No Tokens will be charged.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-free-arcade">Start Free Hour</button>`);
 dialogRoot.querySelector('#confirm-free-arcade')?.addEventListener('click',async()=>{closeDialog();await runArcade(async()=>{if(scope==='class')await arcadeTeacher.setFreeAccess('class');else await Promise.all(selected.map(student=>arcadeTeacher.setFreeAccess('individual',student.id)))},scope==='class'?'Free Arcade is open for everyone for one hour.':`Free Arcade is open for ${names} for one hour.`)});
}
function restoreArcadeRestrictions(scope){
 const selected=students.filter(student=>state.selected.has(student.id));if(scope==='individual'&&!selected.length){showToast('Choose at least one scholar first.');return}
 const names=selected.map(student=>student.name).join(', '),all=scope==='all';
 openDialog(all?'Restore all Arcade restrictions?':'Restore selected Arcade restrictions?',`<p>${all?'Every class and individual free-access grant':'Free access for <b>'+escapeHtml(names)+'</b>'} will end immediately.</p><p class="muted">Normal Morning Work, Curriculum, Token, class, and individual Arcade restrictions will apply again. Any active free session in this scope will close.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-restore-arcade">Restore Restrictions</button>`);
 dialogRoot.querySelector('#confirm-restore-arcade')?.addEventListener('click',async()=>{closeDialog();await runArcade(async()=>{if(all)await arcadeTeacher.setFreeAccess('all','',false);else await Promise.all(selected.map(student=>arcadeTeacher.setFreeAccess('individual',student.id,false)))},all?'All Arcade restrictions restored.':`Arcade restrictions restored for ${names}.`)});
}
function filterRoster(q){const target=document.querySelector('#roster-list');if(target)target.innerHTML=rosterRows(filteredRosterStudents(q));target?.querySelectorAll('[data-student]').forEach(el=>el.addEventListener('change',()=>{el.checked?state.selected.add(el.dataset.student):state.selected.delete(el.dataset.student);render()}))}
function commandEffect(command){return ({'Ready & Working':'+15 XP and +3 Gold','Excellent Transition':'+10 XP and +2 Gold','Great Lunch Behavior':'+20 XP, +4 Gold, and +1 Class Pet point','Great Specials Behavior':'+20 XP, +4 Gold, and +1 Field Trip point','Outstanding Effort':'+30 XP and +6 Gold','Dragonswood Leadership':'+40 XP and +8 Gold','Reset Focus':'−10 XP, never below zero','Pause Access':'Pause optional destinations until a teacher unlocks them','Teacher Check-In':'Require a teacher check-in before optional destinations','Reflection Needed':'Require reflection before optional destinations','Unlock Daily Access':'Unlock today and clear optional-access holds','Pause Optional Area':'Pause optional destinations until a teacher unlocks them','Recognition Note':'Record a positive note in the scholar transaction history','Reset Class Choice':'Clear only classId and preserve pets, equipment, inventory, XP, and Gold','Teacher Flag':'Save a teacher-only follow-up marker'})[command]||'Apply the reviewed teacher command'}
function reviewCommand(command){
 if(!state.selected.size){showToast('Select at least one scholar first.');return}
 if(!command){showToast('Choose a command first.');return}
 if(command==='Full Profile Editor'||command==='Profile Review'){state.pendingCommand='';openProfileReview();return}
 const serious=/Pause|Reset|Reflection/.test(command),custom=/^Custom /.test(command),needsNote=/Note|Flag|Check-In|Reflection|Pause/.test(command);
 openDialog('Review Before Applying',`<div class="selected-badge">${state.selected.size} students selected</div><h3 class="mt-12">${escapeHtml(command)}</h3><p class="muted">${escapeHtml(selectedNames().join(', '))}</p><div class="pass-card"><b>Exact effect</b><p>${escapeHtml(commandEffect(command))}</p></div>${custom?'<div class="field mt-12"><label>Adjustment amount</label><input id="command-amount" type="number" step="1" placeholder="Use a negative number to subtract"></div>':''}<div class="field mt-12"><label>${needsNote?'Teacher note / reason':'Reason (optional)'}</label><textarea id="command-reason" placeholder="Why is this command being applied?"></textarea></div>${serious?'<label class="pass-card serious-warning"><input id="command-serious-confirm" type="checkbox"> I reviewed this access or consequence change and want to apply it.</label>':''}`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn ${serious?'btn-danger':'btn-primary'}" id="apply-student-command">Apply reviewed command</button>`);
 dialogRoot.querySelector('#apply-student-command')?.addEventListener('click',()=>applyReviewedCommand(command,serious));
}
async function applyReviewedCommand(command,serious){
 if(serious&&!dialogRoot.querySelector('#command-serious-confirm')?.checked){showToast('Confirm the serious-action checkbox first.');return}
 const button=dialogRoot.querySelector('#apply-student-command');if(button){button.disabled=true;button.textContent='Applying…'}
 try{const result=await integrationController.applyStudentCommand(command,[...state.selected],{amount:dialogRoot.querySelector('#command-amount')?.value,reason:dialogRoot.querySelector('#command-reason')?.value,note:dialogRoot.querySelector('#command-reason')?.value});state.pendingCommand='';closeDialog();render();showToast(`${command} applied to ${result.students} scholar${result.students===1?'':'s'}.`)}catch(err){if(button){button.disabled=false;button.textContent='Apply reviewed command'}showToast(err?.message||'Command could not be applied.')}
}
function openProfileReview(){
 const chosen=students.filter(student=>state.selected.has(student.id));
 const options=(rows,current)=>rows.map(([value,label])=>`<option value="${escapeHtml(value)}" ${String(current)===String(value)?'selected':''}>${escapeHtml(label)}</option>`).join('');
 const cards=chosen.map(student=>{const uid=escapeHtml(student.id),ownedPets=(student.ownedPets||[]).join(', '),inventory=(student.rpgInventory||[]).join(', '),group=/^girls?$/i.test(student.genderGroup)?'girl':'boy';return `<article class="pass-card profile-editor-card" data-profile-editor="${uid}"><h3>${escapeHtml(student.name)}</h3><p>${escapeHtml(student.email||student.meta)} • Level ${Number(student.level)||1} • ${Number(student.xp)||0} XP</p><div class="form-grid"><div class="profile-editor-section">Identity & placement</div><div class="field"><label>First name</label><input data-profile-field="firstName" maxlength="60" value="${escapeHtml(student.firstName||student.name)}"></div><div class="field"><label>Grade</label><select data-profile-field="grade">${options([[3,'3rd Grade'],[4,'4th Grade'],[5,'5th Grade'],[6,'6th Grade'],[7,'7th Grade'],[8,'8th Grade']],student.grade)}</select></div><div class="field"><label>Gender / group</label><select data-profile-field="genderGroup">${options([['girl','Girls'],['boy','Boys']],group)}</select></div><div class="field"><label>Class</label><select data-profile-field="classId">${options([['','Not chosen'],['warrior','Warrior'],['ranger','Ranger'],['mage','Mage'],['healer','Healer']],student.classId||'')}</select></div><div class="field"><label>Title ID</label><input data-profile-field="title" maxlength="80" value="${escapeHtml(student.title||'')}"></div><div class="field"><label>Avatar ID</label><input data-profile-field="avatar" maxlength="120" value="${escapeHtml(student.avatar||'dragon-purple')}"></div><div class="profile-editor-section">Academic assignments</div><div class="field"><label>Rune Spelling level</label><select data-profile-field="spellingGrade">${options([[3,'Foundation — Grade 3'],[4,'4th Grade'],[5,'5th Grade'],[6,'6th Grade'],[8,'Middle School']],student.spellingGrade)}</select></div><div class="field"><label>Morning Work level</label><select data-profile-field="dailyQuestTrack">${options([['auto','Automatic by profile grade'],['foundation','Foundation — Grade 3'],['4','4th Grade'],['5','5th Grade'],['challenge','6th Grade / Challenge']],student.dailyQuestTrack||'auto')}</select></div><div class="field"><label>Reason for profile edit</label><input data-profile-field="reason" maxlength="240" placeholder="Teacher profile correction"></div><div class="profile-editor-section">Progress</div><div class="field"><label>HP</label><input data-profile-field="hp" type="number" min="0" max="999" value="${Number(student.hp)||0}"></div><div class="field"><label>Gold</label><input data-profile-field="gold" type="number" min="0" max="1000000000" value="${Number(student.gold)||0}"></div><div class="field"><label>XP</label><input data-profile-field="xp" type="number" min="0" max="1000000000" value="${Number(student.xp)||0}"></div><div class="field"><label>Woodland eggs</label><input data-profile-field="eggInventory" type="number" min="0" max="999" value="${Number(student.eggInventory)||0}"></div><div class="field"><label>Boss wins</label><input data-profile-field="bossWins" type="number" min="0" max="10000" value="${Number(student.bossWins)||0}"></div><div class="field"><label>Prior day credit</label><input data-profile-field="legacyDayCredit" type="number" min="0" max="180" value="${Number(student.legacyDayCredit)||0}"></div><div class="profile-editor-section">RPG profile</div><div class="field"><label>Active companion ID</label><input data-profile-field="activePet" maxlength="120" value="${escapeHtml(student.activePet||'')}"></div><div class="field"><label>Owned companion IDs</label><input data-profile-field="ownedPets" value="${escapeHtml(ownedPets)}" placeholder="nyx, ember"></div><div class="field"><label>Owned gear IDs</label><input data-profile-field="rpgInventory" value="${escapeHtml(inventory)}" placeholder="item-one, item-two"></div></div><p class="profile-editor-status">This saves only this scholar. Changes to HP, Gold, and XP are recorded in the teacher transaction history.</p><div class="button-row mt-12"><button class="btn btn-primary" type="button" data-save-student-profile="${uid}">Save Full Profile</button><button class="btn btn-danger" type="button" data-delete-student-profile="${uid}" data-student-name="${escapeHtml(student.name)}">Delete student</button></div></article>`}).join('');
 openDialog('Full Student Profile Editor',`<p>Edit identity, class placement, academic assignments, progress, and RPG profile. Deleting a profile removes the student from Dragonswood while preserving historical grades and activity records.</p><div class="stack">${cards}</div>`,`<button class="btn btn-secondary" data-close-dialog>Close profile editor</button>`);
 dialogRoot.querySelector('.dialog')?.classList.add('profile-editor-dialog');
 dialogRoot.querySelectorAll('[data-save-student-profile]').forEach(button=>button.addEventListener('click',()=>saveFullStudentProfile(button)));dialogRoot.querySelectorAll('[data-delete-student-profile]').forEach(button=>button.addEventListener('click',()=>confirmDeleteStudentProfile(button)));
}
async function saveFullStudentProfile(button){const uid=button.dataset.saveStudentProfile,card=button.closest('[data-profile-editor]'),field=key=>card?.querySelector(`[data-profile-field="${key}"]`)?.value,payload={firstName:field('firstName'),grade:field('grade'),genderGroup:field('genderGroup'),classId:field('classId'),title:field('title'),avatar:field('avatar'),spellingGrade:Number(field('spellingGrade')),dailyQuestTrack:field('dailyQuestTrack'),hp:Number(field('hp')),gold:Number(field('gold')),xp:Number(field('xp')),eggInventory:Number(field('eggInventory')),bossWins:Number(field('bossWins')),legacyDayCredit:Number(field('legacyDayCredit')),activePet:field('activePet'),ownedPets:field('ownedPets'),rpgInventory:field('rpgInventory'),reason:field('reason')};button.disabled=true;button.textContent='Saving…';try{await integrationController.updateStudentProfile(uid,payload);button.textContent='Saved ✓';showToast('Full student profile saved.')}catch(err){button.disabled=false;button.textContent='Save Full Profile';showToast(err?.message||'Student profile could not save.')}}
function confirmDeleteStudentProfile(button){const uid=button.dataset.deleteStudentProfile,name=button.dataset.studentName||'this student';openDialog(`Delete ${escapeHtml(name)}?`,`<p><strong>This permanently removes the student profile from the teacher roster and blocks student-portal access.</strong></p><p>Historical grades and activity records are kept for school records. The separate Firebase login account is not deleted.</p><div class="field"><label>Type <strong>${escapeHtml(name)}</strong> to confirm</label><input id="delete-student-confirm-name" autocomplete="off"></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-delete-student" disabled>Delete student</button>`);const input=dialogRoot.querySelector('#delete-student-confirm-name'),confirm=dialogRoot.querySelector('#confirm-delete-student');input?.addEventListener('input',()=>{confirm.disabled=input.value.trim()!==name.trim()});confirm?.addEventListener('click',async()=>{confirm.disabled=true;confirm.textContent='Deleting…';try{await integrationController.deleteStudentProfile(uid);state.selected.delete(uid);closeDialog();render();showToast(`${name} was removed from the student roster.`)}catch(err){confirm.disabled=false;confirm.textContent='Delete student';showToast(err?.message||'Student could not be deleted.')}});input?.focus()}
function confirmScribe(active){if(active){const payload={title:document.querySelector('#scribe-title')?.value||'Morning Quickwrite',mode:document.querySelector('#scribe-mode')?.value||'Quickwrite',writingType:document.querySelector('#scribe-type')?.value||'Narrative',targetSkill:document.querySelector('#scribe-skill')?.value||'Sensory Details',timeMinutes:document.querySelector('#scribe-time')?.value||5,minWords:document.querySelector('#scribe-minimum')?.value||75,prompt:document.querySelector('#scribe-prompt')?.value||''};openDialog('Launch writing mission?',`<p>Students will see <b>${escapeHtml(payload.title)}</b>. This writes to ${writeDestination()}.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-launch">Launch mission</button>`);dialogRoot.querySelector('#confirm-launch').addEventListener('click',async()=>{try{if(integrationController?.launchWritingSession)await integrationController.launchWritingSession(payload);else state.scribeActive=true;closeDialog();render();showToast('Writing mission launched.')}catch(err){closeDialog();showToast(err?.message||'Mission could not launch.')}})}else openDialog('Close writing mission?',`<p>Students will no longer be able to start or change this mission.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-close-scribe">Close mission</button>`),dialogRoot.querySelector('#confirm-close-scribe')?.addEventListener('click',async()=>{try{if(integrationController?.closeWritingSession)await integrationController.closeWritingSession();else state.scribeActive=false;closeDialog();render();showToast('Mission closed.')}catch(err){closeDialog();showToast(err?.message||'Mission could not close.')}})}
function reviewWriting(id){const row=state.scribe?.responses?.find(item=>item.id===id);if(!row){showToast('Response opened for review.');return}openDialog(`Review ${escapeHtml(row.studentName)}`,`<p>${escapeHtml(row.responseText)}</p><div class="form-grid"><div class="field"><label>Score (0–20)</label><input id="writing-review-score" value="${row.teacherScore??''}"></div><div class="field span-3"><label>Teacher feedback</label><textarea id="writing-review-feedback">${escapeHtml(row.teacherFeedback||'')}</textarea></div></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="save-writing-review">Save review</button>`);dialogRoot.querySelector('#save-writing-review')?.addEventListener('click',async()=>{try{await integrationController.reviewWriting(id,dialogRoot.querySelector('#writing-review-score')?.value,dialogRoot.querySelector('#writing-review-feedback')?.value);closeDialog();showToast(`Teacher review saved to ${writeDestination()}.`)}catch(err){closeDialog();showToast(err?.message||'Review could not save.')}})}
async function adjustClassPoints(delta){if(!state.operations||!integrationController?.adjustClassPoints){state.classPoints=Math.max(0,state.classPoints+delta);showToast(`Class points now ${state.classPoints} in prototype.`);render();return}try{const reason=document.querySelector('#class-points-reason')?.value||'Teacher adjustment';await integrationController.adjustClassPoints(delta,reason);showToast(`Class points saved to ${writeDestination()}.`)}catch(err){showToast(err?.message||'Class points could not save.')}}
