async function denyPass(i){const p=state.pendingPasses[i];if(!p)return;const key=`pass:${p.collection}:${p.id}:deny`;if(dwPendingTeacherActions.has(key))return;dwPendingTeacherActions.add(key);try{if(!p.collection||!integrationController?.reviewPass){state.pendingPasses.splice(i,1);showToast(`${p.name}'s request denied locally.`);render();return}const changed=await integrationController.reviewPass(p.collection,p.id,false);showToast(changed===false?'Already reviewed — no change made.':`${p.name}'s request denied.`)}catch(err){showToast(err?.message||'Pass request could not be denied.')}finally{dwPendingTeacherActions.delete(key)}}
async function returnPass(i){const p=state.activePasses[i];if(!p)return;const key=`return:${p.collection}:${p.id}`;if(dwPendingTeacherActions.has(key))return;dwPendingTeacherActions.add(key);try{if(!p.collection||!integrationController?.returnPass){state.activePasses.splice(i,1);showToast(`${p.name} marked returned locally.`);render();return}const changed=await integrationController.returnPass(p.collection,p.id);showToast(changed===false?'Already returned — no change made.':`${p.name} marked returned.`)}catch(err){showToast(err?.message||'Pass could not be closed.')}finally{dwPendingTeacherActions.delete(key)}}
function showPassHistory(){const rows=state.operations?.passHistory||[];openDialog('Pass History',`<div class="stack">${rows.length?rows.slice(0,50).map(row=>`<article class="pass-card"><b>${escapeHtml(row.studentName||'Student')} • ${escapeHtml(row.label||row.type||'Pass')}</b><p>${escapeHtml(row.dateKey||'')} • ${escapeHtml(row.status||'returned')}${row.durationMinutes!==undefined&&row.durationMinutes!==null?` • ${Number(row.durationMinutes)} min`:''}</p></article>`).join(''):'<div class="pass-card"><p>No archived passes are available yet.</p></div>'}</div>`,`<button class="btn btn-primary" data-close-dialog>Close history</button>`)}
function managePassBlackout(){const active=state.operations?.passBlackout?.active===true;if(active){openDialog('End Pass Blackout?',`<p>Students will be able to use normal pass rules again.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-pass-blackout">End blackout</button>`)}else{openDialog('Start Pass Blackout?',`<p>New pass starts will pause until you end the blackout. Active students can still return their passes.</p><div class="field"><label>Reason shown to students</label><input id="pass-blackout-reason" value="Teacher-directed classroom pause"></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-pass-blackout">Start blackout</button>`)}dialogRoot.querySelector('#confirm-pass-blackout')?.addEventListener('click',async()=>{try{await integrationController.setPassBlackout(!active,dialogRoot.querySelector('#pass-blackout-reason')?.value||'');closeDialog();showToast(`Pass blackout ${active?'ended':'started'}.`)}catch(err){showToast(err?.message||'Pass blackout could not update.')}})}
function manageSubstituteMode(){const current=state.operations?.substituteMode||{},active=current.active===true;if(active){openDialog('End Substitute Mode?',`<p>${current.afternoon?'The free one-hour Afternoon Substitute window will close immediately.':current.arcadeFree?'Free Arcade for Everyone will close immediately.':'Normal student access will return immediately. Regular teacher unlock rules still apply.'}</p>`,`<button class="btn btn-secondary" data-close-dialog>Keep it on</button><button class="btn btn-primary" id="end-substitute-mode">End Substitute Mode</button>`);dialogRoot.querySelector('#end-substitute-mode')?.addEventListener('click',()=>saveSubstituteMode('off',dialogRoot.querySelector('#end-substitute-mode')));return}openDialog('Choose Substitute Mode',`<div class="pass-card serious-warning"><b>Full-Day Substitute Lockdown</b><p>Passes, Kingdom Wars, Deep Time Lab, Dragon Tongues, Arcade, and Boss Battle stay closed through the school day.</p></div><div class="pass-card"><b>🎮 Afternoon Substitute Day • 1 hour</b><p>Students who finish today’s Morning Work and every current Curriculum Quest lesson unlock Quest Games and Arcade free.</p></div><div class="pass-card"><b>🕹️ Free Arcade for Everyone • 1 hour</b><p>Arcade is free for every student regardless of any work status. No Tokens are charged.</p></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="start-full-substitute">Full-Day Lockdown</button><button class="btn btn-secondary" id="start-afternoon-substitute">Afternoon • 1 Hour</button><button class="btn btn-primary" id="start-free-arcade">Free Arcade • 1 Hour</button>`);dialogRoot.querySelector('#start-full-substitute')?.addEventListener('click',()=>saveSubstituteMode('full-day',dialogRoot.querySelector('#start-full-substitute')));dialogRoot.querySelector('#start-afternoon-substitute')?.addEventListener('click',()=>saveSubstituteMode('afternoon',dialogRoot.querySelector('#start-afternoon-substitute')));dialogRoot.querySelector('#start-free-arcade')?.addEventListener('click',()=>saveSubstituteMode('arcade-free',dialogRoot.querySelector('#start-free-arcade')))}
async function saveSubstituteMode(mode,button){if(button){button.disabled=true;button.textContent='Saving…'}try{await integrationController.setSubstituteMode(mode);closeDialog();showToast(mode==='off'?'Substitute Mode ended.':mode==='afternoon'?'Afternoon Substitute Day is open for one hour.':mode==='arcade-free'?'Arcade is free for everyone for one hour.':'Full-Day Substitute Mode is on.')}catch(err){if(button)button.disabled=false;showToast(err?.message||'Substitute Mode could not update.')}}
function recognitionReview(){const rows=state.operations?.recognition||[];if(!rows.length){showToast('No recognition requests are waiting.');return}openDialog('Recognition Requests',`<div class="stack">${rows.map(row=>`<div class="pass-card"><div class="pass-row"><div><b>${escapeHtml(row.name)}</b><p>${escapeHtml(row.reason)} • ${escapeHtml(row.time)}</p></div><div class="pass-actions"><button class="btn btn-primary btn-sm" data-recognition-approve="${escapeHtml(row.id)}">Approve +1 XP</button><button class="btn btn-danger btn-sm" data-recognition-dismiss="${escapeHtml(row.id)}">Dismiss</button></div></div></div>`).join('')}</div>`);dialogRoot.querySelectorAll('[data-recognition-approve]').forEach(button=>button.addEventListener('click',()=>reviewRecognition(button.dataset.recognitionApprove,true)));dialogRoot.querySelectorAll('[data-recognition-dismiss]').forEach(button=>button.addEventListener('click',()=>reviewRecognition(button.dataset.recognitionDismiss,false)))}
async function reviewRecognition(id,approve){const key=`recognition:${id}`;if(dwPendingTeacherActions.has(key))return;dwPendingTeacherActions.add(key);try{const changed=await integrationController.reviewRecognition(id,approve);if(changed!==false)closeDialog();showToast(changed===false?'Already reviewed — no change made.':approve?'Recognition approved and +1 XP recorded.':'Recognition request dismissed.')}catch(err){showToast(err?.message||'Recognition request could not be reviewed.')}finally{dwPendingTeacherActions.delete(key)}}
