function showPointLedger(){const rows=state.operations?.transactions||[];openDialog('Student Point Sync Ledger',`<p>These are the authoritative student profile writes. Each receipt shows the exact before, change, and after values.</p><div class="stack">${rows.length?rows.slice(0,50).map(row=>`<article class="pass-card"><b>${escapeHtml(row.studentName||'Scholar')} • ${escapeHtml(String(row.stat||'').toUpperCase())}</b><p>${Number(row.before)||0} ${Number(row.amount)>=0?'+':''}${Number(row.amount)||0} = ${Number(row.after)||0} • ${escapeHtml(row.reason||'Teacher command')}</p></article>`).join(''):'<p class="muted">No point receipts have been recorded yet.</p>'}</div>`,'<button class="btn btn-primary" data-close-dialog>Close ledger</button>')}
