function exportGradebookCsv(){const gradebook=state.gradebook||{},rows=(gradebook.rows||[]).filter(row=>state.gradeFilter==='All'||String(row.grade)===state.gradeFilter);if(!rows.length){showToast('No live gradebook rows are available to export.');return}if(Number(gradebook.gradeIntegrityVersion)<8||gradebook.reportCardPercentageReady!==true){showToast('Point export is locked until academic evidence passes the grade-integrity checks.');return}const quote=value=>`"${String(value??'').replaceAll('"','""')}"`,assignments=new Map();rows.forEach(row=>(row.assignments||[]).forEach(item=>assignments.set(item.id,item)));const cols=[...assignments.values()].sort((a,b)=>String(b.dateKey||'').localeCompare(String(a.dateKey||''))),lines=[['Scholar','Grade','Overall %','Letter','Points Earned','Points Possible','Status','Missing',...cols.flatMap(item=>[`${item.title} Earned`,`${item.title} Possible`,`${item.title} %`,`${item.title} Status`])],...rows.map(row=>{const byId=new Map((row.assignments||[]).map(item=>[item.id,item]));return [row.name,row.grade,row.total??'',gradeLetter(row.total),row.pointsEarned??'',row.pointsPossible??'',row.totalStatus,row.missing,...cols.flatMap(col=>{const item=byId.get(col.id);return item?[item.pointsEarned??'',item.pointsPossible??'',item.countedScore??'',item.status]:['','','','Not assigned']})]})].map(row=>row.map(quote).join(','));const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`dragonswood-gradebook-${state.gradeFilter==='All'?'all':`grade-${state.gradeFilter}`}-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Point-based gradebook CSV downloaded.')}
